<template><view class="coop-state" :class="{ 'is-error': !!error }"><u-loading-icon v-if="loading" mode="circle" color="var(--primary-color, #d93833)" /><u-icon v-else :name="error ? 'error-circle' : icon" size="35" color="#a3aab5" /><view class="coop-state__title">{{ loading ? loadingText : error || title }}</view><view v-if="!loading && hint" class="coop-state__hint">{{ hint }}</view><button v-if="error" class="coop-state__retry" @tap="$emit('retry')">重新加载</button></view></template>
<script setup lang="ts">
withDefaults(defineProps<{ loading?: boolean; error?: string; title?: string; hint?: string; icon?: string; loadingText?: string }>(), { loading: false, error: '', title: '暂无记录', hint: '', icon: 'order', loadingText: '正在读取…' })
defineEmits<{ (event: 'retry'): void }>()
</script>
<style scoped lang="scss">.coop-state { padding: 32px 16px; text-align: center; display: flex; align-items: center; flex-direction: column; gap: 8px; background: #fff; border-radius: 8px; }.coop-state__title { color: #52657d; font-size: 14px; line-height: 1.7; word-break: break-word; }.coop-state__hint { font-size: 12px; line-height: 1.8; color: #7a899d; }.coop-state__retry { margin: 8px 0 0; background: #fff; color: var(--primary-color, #d93833); border: 1px solid #dde2e9; font-size: 14px; line-height: 44px; min-height: 44px; padding: 0 16px; border-radius: 24px; }.coop-state__retry::after { border: 0; }</style>
